# The frame rate counter (nxnative/dm/android/gfx_vk_present.c ov_fps): its letters (font_fps.h, generated by devtools/pokopia_hud.py --fps-font) cover every
# character it writes, the font's licence ships beside them, and the frames frame generation adds are counted apart from the game's.
import re, unittest
from pathlib import Path

AND = Path(__file__).resolve().parents[1] / 'nxnative' / 'dm' / 'android'


class FpsCounter(unittest.TestCase):
    def test_letters(self):
        h = (AND / 'font_fps.h').read_text(encoding='utf-8')
        chars = re.search(r'#define FPS_CHARS "([^"]*)"', h).group(1)
        for c in '0123456789FPS->': self.assertIn(c, chars)   # the digits, "FPS", "--" before the first measure, '>' the arrow
        em, cell = int(re.search(r'FPS_EM (\d+)', h).group(1)), int(re.search(r'FPS_CELL (\d+)', h).group(1))
        glyphs = [tuple(map(int, g)) for g in re.findall(r'\{(\d+),(\d+),(-?\d+),(\d+)\}', re.search(r'FPS_G\[(\d+)\] = \{(.*?)\};', h).group(2))]
        self.assertEqual(len(glyphs), len(chars))
        n = len(re.search(r'FPS_A\[\] = \{([^}]*)\}', h).group(1).split(','))
        end = 0
        for adv16, w, left, off in glyphs:
            self.assertEqual(off, end); end = off + w * cell   # packed one after another, w x FPS_CELL each
            self.assertTrue(0 < adv16 / 16 < 2 * em)
        self.assertEqual(n, end)
        self.assertIn('SIL Open Font License', h)
        lic = (AND / 'fonts/OFL-MPLUSRounded1c.txt').read_text(encoding='utf-8')
        self.assertIn('Copyright 2016 The Rounded M+ Project Authors.', lic)
        self.assertIn('SIL OPEN FONT LICENSE Version 1.1', lic)

    def test_frame_generation_counted_apart(self):
        src = (AND / 'gfx_vk_present.c').read_text(encoding='utf-8')
        self.assertIn('#include "font_fps.h"', src)
        self.assertEqual(src.count('atomic_fetch_add(&g_fps_gen, 1)'), 2)      # the LSFG frames and the in-between frame
        self.assertEqual(src.count('atomic_fetch_add(&g_fps_frames, 1)'), 1)   # the game's own, in mtl_present
        self.assertIn('"%d > %d FPS"', src)

    def test_frame_generation_quality(self):   # the Display tab's Frame gen quality: LSFG's motion scale and basic frame generation's field density
        lay = (AND / 'overlay_layout.h').read_text(encoding='utf-8')
        self.assertIn('{OVM_ASPECT, OVM_FSR, OVM_SHARP, OVM_FG, OVM_SCALE, OVM_FGQ, OVM_VRS}', lay)
        front = (AND / 'front_android.c').read_text(encoding='utf-8')
        self.assertIn('"fgq=%d"', front); self.assertIn('item == OVM_FGQ ? DISP_FGQ', front)
        self.assertIn('F.flow != flow', (AND / 'gfx_vk_lsfg.c').read_text(encoding='utf-8'))   # LSFG's chain made again when the quality changes
        self.assertIn('FD[dm_disp(DISP_FGQ) & 3]', (AND / 'gfx_vk_fx.h').read_text(encoding='utf-8'))
        src = (AND / 'gfx_vk_present.c').read_text(encoding='utf-8')
        self.assertEqual(src.count('fg_wait_ns('), 3)   # its definition, LSFG's waits and basic frame generation's


if __name__ == '__main__':
    unittest.main()
